Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",

  "data": {
    "name": "dataset"
  },

  "width": "container",
  "height": "container",

  "transform": [

    {
      "calculate": "''Area''",
      "as": "DataType"
    },

    {
      "calculate": "datum[''Area'']",
      "as": "XCategory"
    },

    {
      "calculate": "datum[''Area''] === ''KV 1'' ? 1 : datum[''Area''] === ''KV 2'' ? 2 : datum[''Area''] === ''KV 3'' ? 3 : datum[''Area''] === ''KV 4'' ? 4 : datum[''Area''] === ''KV 5'' ? 5 : 99",
      "as": "XSort"
    },

    {
      "calculate": "datum[''Heatmap Value'']",
      "as": "DisplayValue"
    },

    {
      "calculate": "datum[''Heatmap Label'']",
      "as": "DisplayLabel"
    },

    {
      "calculate": "abs(datum[''Heatmap Value''])",
      "as": "AbsValue"
    },

    {
      "joinaggregate": [
        {
          "op": "max",
          "field": "AbsValue",
          "as": "MaxAbsValue"
        }
      ]
    },

    {
      "calculate": "datum.MaxAbsValue === 0 || datum.MaxAbsValue == null ? 0 : datum[''Heatmap Value''] / datum.MaxAbsValue",
      "as": "ColorRatio"
    },

    {
      "calculate": "datum[''Heatmap Total Value'']",
      "as": "TotalValue"
    },

    {
      "calculate": "datum[''Heatmap Total Label'']",
      "as": "TotalLabel"
    },

    {
      "calculate": "''TỔNG''",
      "as": "TotalXCategory"
    }
  ],

  "encoding": {

    "x": {
      "field": "XCategory",
      "type": "nominal",

      "sort": {
        "field": "XSort",
        "op": "min",
        "order": "ascending"
      },

      "scale": {
        "paddingInner": 0.08,
        "paddingOuter": 0.02
      },

      "axis": {
        "orient": "top",
        "title": null,
        "labelAngle": 0,
        "labelFontSize": 14,
        "labelPadding": 8,
        "domain": false,
        "ticks": false,
        "grid": false
      }
    },

    "y": {
      "field": "Concept",
      "type": "nominal",

      "sort": [
        "Convenience",
        "Mini Mart",
        "Modern Grocery Store",
        "Supermarket"
      ],

      "scale": {
        "paddingInner": 0.08,
        "paddingOuter": 0.02
      },

      "axis": {
        "title": null,
        "labelFontSize": 14,
        "labelPadding": 8,
        "domain": false,
        "ticks": false,
        "grid": false
      }
    }
  },

  "layer": [

    {
      "name": "Detail Cells",

      "mark": {
        "type": "rect",
        "cornerRadius": 4,
        "stroke": "white",
        "strokeWidth": 2
      },

      "encoding": {

        "color": {
          "condition": {
            "test": "!isValid(datum[''Heatmap Value''])",
            "value": "#FFFFFF"
          },

          "field": "ColorRatio",
          "type": "quantitative",

          "scale": {
            "domain": [
              -1,
              0,
              1
            ],

            "range": [
              "#C62828",
              "#FFFFFF",
              "#2E7D32"
            ]
          },

          "legend": null
        },

        "tooltip": [
          {
            "field": "Concept",
            "type": "nominal",
            "title": "Concept"
          },

          {
            "field": "Khu vực",
            "type": "nominal",
            "title": "Khu vực"
          },

          {
            "field": "Heatmap Label",
            "type": "nominal",
            "title": "Giá trị"
          }
        ]
      }
    },

    {
      "name": "Detail Labels",

      "mark": {
        "type": "text",
        "fontSize": 14,
        "fontWeight": "bold",
        "align": "center",
        "baseline": "middle"
      },

      "transform": [
        {
          "filter": "isValid(datum[''Heatmap Label'']) && datum[''Heatmap Label''] !== ''''"
        }
      ],

      "encoding": {

        "text": {
          "field": "Heatmap Label",
          "type": "nominal"
        },

        "color": {
          "condition": [
            {
              "test": "abs(datum.ColorRatio) >= 0.55",
              "value": "white"
            }
          ],

          "value": "black"
        }
      }
    },

    {
      "name": "Total Cells",

      "transform": [

        {
          "calculate": "datum[''Heatmap Total Value'']",
          "as": "TotalValue"
        },

        {
          "calculate": "datum[''Heatmap Total Label'']",
          "as": "TotalLabel"
        },

        {
          "calculate": "abs(datum[''Heatmap Total Value''])",
          "as": "TotalAbsValue"
        },

        {
          "joinaggregate": [
            {
              "op": "max",
              "field": "TotalAbsValue",
              "as": "MaxTotalAbsValue"
            }
          ]
        },

        {
          "calculate": "datum.MaxTotalAbsValue === 0 || datum.MaxTotalAbsValue == null ? 0 : datum.TotalValue / datum.MaxTotalAbsValue",
          "as": "TotalColorRatio"
        },

        {
          "calculate": "''TỔNG''",
          "as": "XCategory"
        },

        {
          "calculate": "6",
          "as": "XSort"
        },

        {
          "aggregate": [
            {
              "op": "max",
              "field": "TotalValue",
              "as": "TotalValue"
            },

            {
              "op": "max",
              "field": "TotalLabel",
              "as": "TotalLabel"
            },

            {
              "op": "max",
              "field": "TotalColorRatio",
              "as": "TotalColorRatio"
            },

            {
              "op": "max",
              "field": "XSort",
              "as": "XSort"
            }
          ],

          "groupby": [
            "Concept",
            "XCategory"
          ]
        }
      ],

      "mark": {
        "type": "rect",
        "cornerRadius": 4,
        "stroke": "white",
        "strokeWidth": 2
      },

      "encoding": {

        "x": {
          "field": "XCategory",
          "type": "nominal",

          "sort": {
            "field": "XSort",
            "op": "min",
            "order": "ascending"
          }
        },

        "y": {
          "field": "Concept",
          "type": "nominal",

          "sort": [
            "Convenience",
            "Mini Mart",
            "Modern Grocery Store",
            "Supermarket"
          ]
        },

        "color": {
          "condition": {
            "test": "!isValid(datum.TotalValue)",
            "value": "#FFFFFF"
          },

          "field": "TotalColorRatio",
          "type": "quantitative",

          "scale": {
            "domain": [
              -1,
              0,
              1
            ],

            "range": [
              "#287E8F",
              "#FFFFFF",
              "#2E7D32"
            ]
          },

          "legend": null
        },

        "tooltip": [
          {
            "field": "Concept",
            "type": "nominal",
            "title": "Concept"
          },

          {
            "value": "TỔNG",
            "title": "Khu vực"
          },

          {
            "field": "TotalLabel",
            "type": "nominal",
            "title": "Giá trị"
          }
        ]
      }
    },

    {
      "name": "Total Labels",

      "transform": [

        {
          "calculate": "datum[''Heatmap Total Value'']",
          "as": "TotalValue"
        },

        {
          "calculate": "datum[''Heatmap Total Label'']",
          "as": "TotalLabel"
        },

        {
          "calculate": "abs(datum[''Heatmap Total Value''])",
          "as": "TotalAbsValue"
        },

        {
          "joinaggregate": [
            {
              "op": "max",
              "field": "TotalAbsValue",
              "as": "MaxTotalAbsValue"
            }
          ]
        },

        {
          "calculate": "datum.MaxTotalAbsValue === 0 || datum.MaxTotalAbsValue == null ? 0 : datum.TotalValue / datum.MaxTotalAbsValue",
          "as": "TotalColorRatio"
        },

        {
          "calculate": "''TỔNG''",
          "as": "XCategory"
        },

        {
          "calculate": "6",
          "as": "XSort"
        },

        {
          "aggregate": [
            {
              "op": "max",
              "field": "TotalValue",
              "as": "TotalValue"
            },

            {
              "op": "max",
              "field": "TotalLabel",
              "as": "TotalLabel"
            },

            {
              "op": "max",
              "field": "TotalColorRatio",
              "as": "TotalColorRatio"
            },

            {
              "op": "max",
              "field": "XSort",
              "as": "XSort"
            }
          ],

          "groupby": [
            "Concept",
            "XCategory"
          ]
        },

        {
          "filter": "isValid(datum.TotalLabel) && datum.TotalLabel !== ''''"
        }
      ],

      "mark": {
        "type": "text",
        "fontSize": 14,
        "fontWeight": "bold",
        "align": "center",
        "baseline": "middle"
      },

      "encoding": {

        "x": {
          "field": "XCategory",
          "type": "nominal",

          "sort": {
            "field": "XSort",
            "op": "min",
            "order": "ascending"
          }
        },

        "y": {
          "field": "Concept",
          "type": "nominal",

          "sort": [
            "Convenience",
            "Mini Mart",
            "Modern Grocery Store",
            "Supermarket"
          ]
        },

        "text": {
          "field": "TotalLabel",
          "type": "nominal"
        },

        "color": {
          "condition": [
            {
              "test": "abs(datum.TotalColorRatio) >= 0.55",
              "value": "white"
            }
          ],

          "value": "black"
        }
      }
    }
  ],

  "config": {
    "view": {
      "stroke": null
    },

    "axis": {
      "domain": false,
      "ticks": false,
      "grid": false
    }
  }
}'
